css:
.print-format .letter-head {
    margin-top: 0px;
    margin-bottom: 0px;
}

.print-format {
    font-family: Arial, sans-serif;
    font-size: 14px;
    padding: 20px;
}

.text-bold {
    font-weight: bold;
}

.text-underline {
    text-decoration: underline;
}

.letter-header, .letter-body {
    margin-bottom: 20px;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    width: 80%;
    justify-content: space-between;
    margin-left: auto;
    margin-right: auto;
}

table, th {
    border: 1px solid #000;
    padding: 8px;
}
table, td {
    border: 1px solid #000;
    text-align: left;
    padding: 8px;
}

.signature {
    margin-top: 40px;
}

.signature div {
    margin-bottom: 20px;
}
